INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3493630, 487792, 24454, '<td valign="top">Oh yes!  This is gorgeous still!  My favorite photo so far.  I love being in scenes like that that are so quiet and still you can hear the ducks little feet peddling!  Beautiful job!</td>', 'Oh yes!  This is gorgeous still!  My favorite photo so far.  I love being in scenes like that that are so quiet and still you can hear the ducks little feet peddling!  Beautiful job!', '2007-03-28 10:44:50.000000', NULL, 1),
(3493634, 486985, 16154, '<td valign="top">Awesome reds! Can''t believe its only filters! 9</td>', 'Awesome reds! Can''t believe its only filters! 9', '2007-03-28 10:45:34.000000', NULL, 1),
(3493635, 489538, 23484, '<td valign="top">To me, this really doesn''t show still.</td>', 'To me, this really doesn''t show still.', '2007-03-28 10:46:14.000000', NULL, 1),
(3493638, 489303, 24454, '<td valign="top">Ohmygoodness!  This is certainly the prettiest still I''ve seen so far in this challenge!  Fabulous photo.</td>', 'Ohmygoodness!  This is certainly the prettiest still I''ve seen so far in this challenge!  Fabulous photo.', '2007-03-28 10:46:44.000000', NULL, 1),
(3493639, 486985, 23484, '<td valign="top">Very nice shot. meets the challenge well.</td>', 'Very nice shot. meets the challenge well.', '2007-03-28 10:47:34.000000', NULL, 1),
(3493640, 488042, 24454, '<td valign="top">This is awesome!  I see this as a wall print!  In fact, I have a wall print something like this :)</td>', 'This is awesome!  I see this as a wall print!  In fact, I have a wall print something like this :)', '2007-03-28 10:48:04.000000', NULL, 1),
(3493650, 487589, 24454, '<td valign="top">I love this photo!  I don''t know what it is about having a canoe in a water photo that just bumps up the appeal so much, but it really does.  Great job.</td>', 'I love this photo!  I don''t know what it is about having a canoe in a water photo that just bumps up the appeal so much, but it really does.  Great job.', '2007-03-28 10:50:40.000000', NULL, 1),
(3493657, 489133, 24454, '<td valign="top">Oh how AWESOME!  The thumbnail totally doesn''t do it justice.  The texture and contrasting softness vs. sharpness makes this a standout!  Fantastic still photo!</td>', 'Oh how AWESOME!  The thumbnail totally doesn''t do it justice.  The texture and contrasting softness vs. sharpness makes this a standout!  Fantastic still photo!', '2007-03-28 10:52:29.000000', NULL, 1),
