(3496919, 489462, 76153, '<td valign="top">I would have liked if the picture showed more of the "closed" feel; it seems merely not moving, and not abandoned, as the title entails.</td>', 'I would have liked if the picture showed more of the "closed" feel; it seems merely not moving, and not abandoned, as the title entails.', '2007-03-29 14:21:14.000000', NULL, 1),
(3496921, 488257, 76153, '<td valign="top">A little out of focus.</td>', 'A little out of focus.', '2007-03-29 14:21:48.000000', NULL, 1),
