(3497187, 489074, 30822, '<td valign="top">Nice pic but way o oversharpened.</td>', 'Nice pic but way o oversharpened.', '2007-03-29 16:06:21.000000', NULL, 1),
(3497190, 487608, 30822, '<td valign="top">The angle and all the extra blcak dosen''t appeal to me. MAybe closer to the light.</td>', 'The angle and all the extra blcak dosen''t appeal to me. MAybe closer to the light.', '2007-03-29 16:07:10.000000', NULL, 1),
(3497191, 489538, 45857, '<td valign="top">Good image, pity about getting it in wrong challenge</td>', 'Good image, pity about getting it in wrong challenge', '2007-03-29 16:07:28.000000', NULL, 1),
(3497194, 487646, 61651, '<td valign="top">The overall mood of stillness is captured well here, but there are some elements that for me make the image less effective.  The sky seems to be very noisy (an unavoidable side-effect of the fog?) and in the top part of the sky the highlights are blown.  Would also have liked to have a clear view of the barn, without that one shrub blocking it.</td>', 'The overall mood of stillness is captured well here, but there are some elements that for me make the image less effective.  The sky seems to be very noisy (an unavoidable side-effect of the fog?) and in the top part of the sky the highlights are blown.  Would also have liked to have a clear view of the barn, without that one shrub blocking it.', '2007-03-29 16:08:51.000000', NULL, 1),
(3497195, 487554, 30822, '<td valign="top">Way to oversharpned IMHO. Also the areas in the trees in the background and the leaves give away the fact the clouds were darkened.</td>', 'Way to oversharpned IMHO. Also the areas in the trees in the background and the leaves give away the fact the clouds were darkened.', '2007-03-29 16:08:57.000000', NULL, 1),
(3497196, 489168, 30822, '<td valign="top">His cheek is blownout IMHO.</td>', 'His cheek is blownout IMHO.', '2007-03-29 16:09:36.000000', NULL, 1),
(3497197, 489560, 30822, '<td valign="top">Nice technically but no real wow factor.</td>', 'Nice technically but no real wow factor.', '2007-03-29 16:09:59.000000', NULL, 1),
(3497198, 487446, 30822, '<td valign="top">Nice technically but no real wow factor.</td>', 'Nice technically but no real wow factor.', '2007-03-29 16:10:07.000000', NULL, 1),
(3497199, 489298, 61651, '<td valign="top">This has a very moody and desolate feel to it, a good choice for the challenge, I think.  The image could be improved by bringing more detail out of the shadows - some of the dark parts are just too dark.</td>', 'This has a very moody and desolate feel to it, a good choice for the challenge, I think.  The image could be improved by bringing more detail out of the shadows - some of the dark parts are just too dark.', '2007-03-29 16:10:07.000000', NULL, 1),
