(3498541, 487754, 74037, '<td valign="top">interesting color</td>', 'interesting color', '2007-03-29 23:42:05.000000', NULL, 1),
(3498557, 489478, 74496, '<td valign="top">interesting subject!  I find the hot spots in the background distracting though, especially for still.</td>', 'interesting subject!  I find the hot spots in the background distracting though, especially for still.', '2007-03-29 23:54:03.000000', NULL, 1),
(3498562, 489135, 74496, '<td valign="top">the tilt to the right is a little strange, feels more like motion than still</td>', 'the tilt to the right is a little strange, feels more like motion than still', '2007-03-29 23:55:21.000000', NULL, 1),
(3498565, 486826, 67258, '<td valign="top">The sense of motion of the passers-by certainly helps to reinforce the stillness of your central subject. An interesting and thought-provoking photograph with a strong narrative.</td>', 'The sense of motion of the passers-by certainly helps to reinforce the stillness of your central subject. An interesting and thought-provoking photograph with a strong narrative.', '2007-03-29 23:56:48.000000', NULL, 1),
(3498672, 487342, 69966, '<td valign="top">not very good color contrast</td>', 'not very good color contrast', '2007-03-30 00:52:30.000000', NULL, 1),
(3498674, 486797, 69966, '<td valign="top">great capture!</td>', 'great capture!', '2007-03-30 00:52:55.000000', NULL, 1),
(3498675, 489215, 69966, '<td valign="top">great clarity!</td>', 'great clarity!', '2007-03-30 00:53:07.000000', NULL, 1),
(3498676, 487111, 69966, '<td valign="top">maybe select a better background to enhance the watch even more</td>', 'maybe select a better background to enhance the watch even more', '2007-03-30 00:53:41.000000', NULL, 1),
(3498678, 488478, 69966, '<td valign="top">could be zoomed in more to offer better detail</td>', 'could be zoomed in more to offer better detail', '2007-03-30 00:54:03.000000', NULL, 1),
(3498727, 489288, 20124, '<td valign="top">Classic Still Life. I like the depth of field contrast between the<br/>clear pear in front and the blurred one in back. I just wish the table was<br/>of a darker color to add even more contrast to the yellowish <br/>pears. Seven.</td>', 'Classic Still Life. I like the depth of field contrast between theclear pear in front and the blurred one in back. I just wish the table wasof a darker color to add even more contrast to the yellowish pears. Seven.', '2007-03-30 01:26:55.000000', NULL, 1),
(3498738, 489469, 20124, '<td valign="top">Bambi! <br/> <br/>A little blurry.  A minor sharpness adjustment would have<br/>helped. Otherwise, interesting subject choice.</td>', 'Bambi!  A little blurry.  A minor sharpness adjustment would havehelped. Otherwise, interesting subject choice.', '2007-03-30 01:29:40.000000', NULL, 1),
(3498767, 489088, 20124, '<td valign="top">Bawdy humor is fine when done tastefully and with subtlety.<br/>Brown, wrinkled background also adds color and<br/>texture contrast with the squash.</td>', 'Bawdy humor is fine when done tastefully and with subtlety.Brown, wrinkled background also adds color andtexture contrast with the squash.', '2007-03-30 01:36:25.000000', NULL, 1),
(3498788, 488821, 20124, '<td valign="top">I like the nice positioning of the fruits and vegetables.<br/>I don''t like the dull lighting.</td>', 'I like the nice positioning of the fruits and vegetables.I don''t like the dull lighting.', '2007-03-30 01:47:36.000000', NULL, 1),
(3498789, 489168, 20124, '<td valign="top">Wake up! You need to reduce the annoying glare on right side of his<br/> face. At least it fits the theme.</td>', 'Wake up! You need to reduce the annoying glare on right side of his face. At least it fits the theme.', '2007-03-30 01:49:26.000000', NULL, 1),
(3498798, 489302, 20124, '<td valign="top">Clever.</td>', 'Clever.', '2007-03-30 01:52:42.000000', NULL, 1),
(3498803, 489383, 20124, '<td valign="top">Adorable. A calm two year old boy? Now that''s rare.</td>', 'Adorable. A calm two year old boy? Now that''s rare.', '2007-03-30 01:54:24.000000', NULL, 1),
(3498814, 488039, 20124, '<td valign="top">Usually reflections are a nice touch. But here it takes some focus<br/>away from the bridge. Otherwise, this is well shot. I like how the <br/>trees and hill frame this shot.</td>', 'Usually reflections are a nice touch. But here it takes some focusaway from the bridge. Otherwise, this is well shot. I like how the trees and hill frame this shot.', '2007-03-30 01:57:49.000000', NULL, 1),
(3498822, 488111, 20124, '<td valign="top">The cat is fine, but the all white background makes it look like you<br/>cut and pasted the cat. Also, natural surroundings, even if blurred, makes for a more interesting composition.</td>', 'The cat is fine, but the all white background makes it look like youcut and pasted the cat. Also, natural surroundings, even if blurred, makes for a more interesting composition.', '2007-03-30 02:01:10.000000', NULL, 1),
(3498824, 489205, 20124, '<td valign="top">Not</td>', 'Not', '2007-03-30 02:01:51.000000', NULL, 1),
(3498827, 488871, 49082, '<td valign="top">Oh my God....I love this. Top 3.</td>', 'Oh my God....I love this. Top 3.', '2007-03-30 02:02:45.000000', NULL, 1),
(3498838, 486774, 60124, '<td valign="top">You might want to try some bounce flash, as it would remove the stark casting caused by direct flash.</td>', 'You might want to try some bounce flash, as it would remove the stark casting caused by direct flash.', '2007-03-30 02:06:23.000000', NULL, 1),
(3498843, 489387, 60124, '<td valign="top">Excellent macro</td>', 'Excellent macro', '2007-03-30 02:07:16.000000', NULL, 1),
(3498852, 489121, 60124, '<td valign="top">Beautiful effect with the stars</td>', 'Beautiful effect with the stars', '2007-03-30 02:09:56.000000', NULL, 1),
(3498854, 488385, 60124, '<td valign="top">I wonder how this would look if applied some HDR (though outside the scope of this challenge.)</td>', 'I wonder how this would look if applied some HDR (though outside the scope of this challenge.)', '2007-03-30 02:10:43.000000', NULL, 1),
(3498856, 489344, 60124, '<td valign="top">Beautiful macro!</td>', 'Beautiful macro!', '2007-03-30 02:11:06.000000', NULL, 1),
(3498857, 489560, 60124, '<td valign="top">Very interesting color curves.</td>', 'Very interesting color curves.', '2007-03-30 02:11:30.000000', NULL, 1),
(3498859, 488871, 60124, '<td valign="top">I like the way the fog obscures the edges</td>', 'I like the way the fog obscures the edges', '2007-03-30 02:12:19.000000', NULL, 1),
(3498862, 489032, 60124, '<td valign="top">Great capture of the evening colors.</td>', 'Great capture of the evening colors.', '2007-03-30 02:14:14.000000', NULL, 1),
(3498866, 488884, 60124, '<td valign="top">Did you leave your filter on, or is the reddish spot from within the lens?</td>', 'Did you leave your filter on, or is the reddish spot from within the lens?', '2007-03-30 02:15:46.000000', NULL, 1),
(3498868, 487332, 60124, '<td valign="top">Interesting color saturation.</td>', 'Interesting color saturation.', '2007-03-30 02:16:03.000000', NULL, 1),
