(3498974, 486985, 56696, '<td valign="top">holy shit</td>', 'holy shit', '2007-03-30 03:36:39.000000', NULL, 1),
(3499023, 489482, 36999, '<td valign="top">I''d like a little more DOF so the bit was in focus too.  Hairs seems a bit oversharpened.  love that his nose is lopsided, cute.  nice color and exposure</td>', 'I''d like a little more DOF so the bit was in focus too.  Hairs seems a bit oversharpened.  love that his nose is lopsided, cute.  nice color and exposure', '2007-03-30 04:34:25.000000', NULL, 1),
(3499024, 489541, 36999, '<td valign="top">The crop could be improved.  I like the idea of the branches showing motion</td>', 'The crop could be improved.  I like the idea of the branches showing motion', '2007-03-30 04:35:08.000000', NULL, 1),
(3499026, 487378, 36999, '<td valign="top">nice subject.  I like the road in the background, I wish the sky had either more cloud texture or color</td>', 'nice subject.  I like the road in the background, I wish the sky had either more cloud texture or color', '2007-03-30 04:36:50.000000', NULL, 1),
(3499032, 487646, 32872, '<td valign="top">pretty and evokes ''stillness''.</td>', 'pretty and evokes ''stillness''.', '2007-03-30 04:44:20.000000', NULL, 1),
(3499051, 489335, 44611, '<td valign="top">I suspect you may have entered this in the wrong challenge.. it really doesn''t represent still to me in the slightest.</td>', 'I suspect you may have entered this in the wrong challenge.. it really doesn''t represent still to me in the slightest.', '2007-03-30 05:47:39.000000', NULL, 1),
(3499052, 489141, 44611, '<td valign="top">Gives a feeling of stillness definitely, but rather uninteresting as a subject.</td>', 'Gives a feeling of stillness definitely, but rather uninteresting as a subject.', '2007-03-30 05:48:09.000000', NULL, 1),
(3499053, 486764, 44611, '<td valign="top">Its a shame that the composition of this is rather boring - the idea, I think, was excellent and the leading lines of the building could have a real wow factor.  More contrast in the sky would have helped too.</td>', 'Its a shame that the composition of this is rather boring - the idea, I think, was excellent and the leading lines of the building could have a real wow factor.  More contrast in the sky would have helped too.', '2007-03-30 05:49:18.000000', NULL, 1),
(3499054, 488913, 44611, '<td valign="top">Great depth of field.</td>', 'Great depth of field.', '2007-03-30 05:50:01.000000', NULL, 1),
(3499055, 487697, 44611, '<td valign="top">Great subject, lots of interest.  Really brings back those memories of being told to sit still and be quiet!</td>', 'Great subject, lots of interest.  Really brings back those memories of being told to sit still and be quiet!', '2007-03-30 05:50:53.000000', NULL, 1),
(3499056, 489032, 44611, '<td valign="top">The central position of the tree makes this shot rather uninteresting... the silhouette and colour are good though.</td>', 'The central position of the tree makes this shot rather uninteresting... the silhouette and colour are good though.', '2007-03-30 05:52:47.000000', NULL, 1),
(3499057, 487287, 44611, '<td valign="top">Great angle and really works in b &amp; w.</td>', 'Great angle and really works in b & w.', '2007-03-30 05:53:24.000000', NULL, 1),
(3499058, 488172, 44611, '<td valign="top">Great use of a slow shutter speed. The way the static furniture in colour stands out against the rather monochrome moving figures is brilliant.</td>', 'Great use of a slow shutter speed. The way the static furniture in colour stands out against the rather monochrome moving figures is brilliant.', '2007-03-30 05:54:55.000000', NULL, 1),
(3499059, 489355, 44611, '<td valign="top">Great scene, but the lighting and exposure don''t do it justice in my view.</td>', 'Great scene, but the lighting and exposure don''t do it justice in my view.', '2007-03-30 05:55:39.000000', NULL, 1),
(3499060, 487685, 44611, '<td valign="top">The elaborate framing is rather distracting with such a simple subject.</td>', 'The elaborate framing is rather distracting with such a simple subject.', '2007-03-30 05:56:25.000000', NULL, 1),
(3499061, 486934, 44611, '<td valign="top">A potentially good idea, not taken quite far enough I think.  The central positioning of the lemon makes the shot rather static and a greater depth of field would have isolated the subject better.  As it is the hedge in the background is too distracting.</td>', 'A potentially good idea, not taken quite far enough I think.  The central positioning of the lemon makes the shot rather static and a greater depth of field would have isolated the subject better.  As it is the hedge in the background is too distracting.', '2007-03-30 05:58:37.000000', NULL, 1),
