(3499931, 488057, 74765, '<td valign="top">The foreground object is unsharp and hides to much of the background, it overtakes the nice landscape.</td>', 'The foreground object is unsharp and hides to much of the background, it overtakes the nice landscape.', '2007-03-30 15:17:59.000000', NULL, 1),
(3499932, 488913, 73235, '<td valign="top">I can see your composition, using the handle to fill the negative space is distracting from your focus point - the rose. while the eye should be led across a picture and routed back to your focal point, the bacground rose leads the viewer away from your amin object.</td>', 'I can see your composition, using the handle to fill the negative space is distracting from your focus point - the rose. while the eye should be led across a picture and routed back to your focal point, the bacground rose leads the viewer away from your amin object.', '2007-03-30 15:18:17.000000', NULL, 1),
