(3506129, 489101, 61961, '<td valign="top">Fits the theme; nice composition and I like the red of the dress, the black of the shirt and the whiteness of her skin.  Attractive model.  It may be an illusion but her eyes don''t seem as sharply focussed as other parts of the photo.</td>', 'Fits the theme; nice composition and I like the red of the dress, the black of the shirt and the whiteness of her skin.  Attractive model.  It may be an illusion but her eyes don''t seem as sharply focussed as other parts of the photo.', '2007-04-01 17:16:33.000000', NULL, 1),
(3506132, 489419, 61961, '<td valign="top">This doesn''t seem still or serene to me, it looks like a half-eaten pear thrown in a pond (or a naked muppet snorkling).  Sorry, it''s getting late and I''m getting punchy.</td>', 'This doesn''t seem still or serene to me, it looks like a half-eaten pear thrown in a pond (or a naked muppet snorkling).  Sorry, it''s getting late and I''m getting punchy.', '2007-04-01 17:17:49.000000', NULL, 1),
(3506137, 489454, 73235, '<td valign="top">absolutely meets the challenge, what a beauty of a still life!</td>', 'absolutely meets the challenge, what a beauty of a still life!', '2007-04-01 17:19:38.000000', NULL, 1),
