(3516403, 488100, 32147, '<td valign="top">nice minimalistic shot.</td>', 'nice minimalistic shot.', '2007-04-03 22:46:17.000000', NULL, 1),
(3516405, 489505, 49625, '<td valign="top">Great color!</td>', 'Great color!', '2007-04-03 22:46:33.000000', NULL, 1),
(3516409, 489467, 32147, '<td valign="top">indeed!  Appropriate title and the shot fits the challenge nicely.  <br/> <br/>I only wonder one thing - and it might be a bit on the picky side - but wouldnt a corpses feet be a bit less colorful?  <br/> <br/>Black and white would really go well here, or use a saturation adjustment layer to reduce the overall color.  I think that is allowed in basic if I am not mistaken.<br/> <br/>-8-</td>', 'indeed!  Appropriate title and the shot fits the challenge nicely.   I only wonder one thing - and it might be a bit on the picky side - but wouldnt a corpses feet be a bit less colorful?   Black and white would really go well here, or use a saturation adjustment layer to reduce the overall color.  I think that is allowed in basic if I am not mistaken. -8-', '2007-04-03 22:48:28.000000', NULL, 1),
(3516411, 489510, 32147, '<td valign="top">great capture and excellent use of bokeh to bring color and softness to the background.</td>', 'great capture and excellent use of bokeh to bring color and softness to the background.', '2007-04-03 22:48:58.000000', NULL, 1),
