(3580370, 489387, 48560, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Techo:</b></div><hr/><i> Really like this whole concept and setup. The fibers remind me of cobwebs and the blue background works nicely. Do think though that the leaf looks overprocessed, which doesn''t make it fit in as well with rest of the shot''s appearance. </i></td></tr></table> <br/> <br/>i agree with Techo about how the leaf appeared over-processed. maybe it''s meant to stand out among the rest of the photo, but it''s a little overdone (maybe just by a tiny bit ;) ) overall this photo has a certain simplicity that is very nice!</td>', 'Originally posted by Techo: Really like this whole concept and setup. The fibers remind me of cobwebs and the blue background works nicely. Do think though that the leaf looks overprocessed, which doesn''t make it fit in as well with rest of the shot''s appearance.   i agree with Techo about how the leaf appeared over-processed. maybe it''s meant to stand out among the rest of the photo, but it''s a little overdone (maybe just by a tiny bit ;) ) overall this photo has a certain simplicity that is very nice!', '2007-04-25 06:02:03.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3582949, 489074, 5792, '<td valign="top"><b>Positives:</b> <br/>Composition is the strength of this image. Has good balance between objects and reflections given the near center framing of the water''s edge. Wwell done. Very peaceful, traquil image.<br/> <br/><b>Technicals:</b> <br/>Composition and content are excellent. Color is generally good. It is immediately obvious that some type of HDRI process has been applied... Shadow/Highlight in this particular case. With it you brought out great lighting and detail in the reeds. Shadow/Highlight is tricky to learn and use and sometimes leaves a surrealistic, unnatural look to the lighting from its narrowing of lighting differences. That has happened to a certain degree in this case. You didn''t get any of the ugly haloing that we sometimes see but you pushed the limit. The best applications of these techniques are the ones least obvious. Your treatment is not bad, but could be better.<br/> <br/>I''m on a sharpness sensitive monitor and can see "jaggies" typical of oversharpening. It is most apparent in the plant above and over the top of the bird. <br/> <br/><b>The Challenge:</b> <br/>The shot selection of a tranquil natural scene fits the challenge quite nicely but some voters, like the one commenting it would be better if the water were "still", might lower the score for the ripples in the water. Your score of 5.9 is decent by DPC group standards and that likely comes from the strength of composition, subject selection and the final look of the reeds over its other technical aspects.<br/> <br/><b>Suggestions:</b> <br/>You might want to back off on the sharpening a bit. Shadow/highlight, since it changes brightness and contrast, affects sharpening and makes it easier to oversharpen.<br/> <br/>As an experiment try redoing this image with shadow/highlight to the point that the casual observer cannot tell that anything of that nature has been done to the image. It is a skill you will want to perfect for other images where a more natural look is desired.<br/><br/><i>Message edited by author 2007-04-25 18:26:54.</i></td>', 'Positives: Composition is the strength of this image. Has good balance between objects and reflections given the near center framing of the water''s edge. Wwell done. Very peaceful, traquil image. Technicals: Composition and content are excellent. Color is generally good. It is immediately obvious that some type of HDRI process has been applied... Shadow/Highlight in this particular case. With it you brought out great lighting and detail in the reeds. Shadow/Highlight is tricky to learn and use and sometimes leaves a surrealistic, unnatural look to the lighting from its narrowing of lighting differences. That has happened to a certain degree in this case. You didn''t get any of the ugly haloing that we sometimes see but you pushed the limit. The best applications of these techniques are the ones least obvious. Your treatment is not bad, but could be better. I''m on a sharpness sensitive monitor and can see "jaggies" typical of oversharpening. It is most apparent in the plant above and over the top of the bird.  The Challenge: The shot selection of a tranquil natural scene fits the challenge quite nicely but some voters, like the one commenting it would be better if the water were "still", might lower the score for the ripples in the water. Your score of 5.9 is decent by DPC group standards and that likely comes from the strength of composition, subject selection and the final look of the reeds over its other technical aspects. Suggestions: You might want to back off on the sharpening a bit. Shadow/highlight, since it changes brightness and contrast, affects sharpening and makes it easier to oversharpen. As an experiment try redoing this image with shadow/highlight to the point that the casual observer cannot tell that anything of that nature has been done to the image. It is a skill you will want to perfect for other images where a more natural look is desired.', '2007-04-25 19:25:56.000000', '2007-04-25 19:26:54.000000', 0),
(3583352, 489328, 70514, '<td valign="top">James, this really tugged at my heart strings as I''m a runner.  Since I''ve been home with my girls though, I don''t get out to the local running "path" like I used to.  Nice job capturing that emotion.  (not that it matters, but I gave this an 8 during voting.)</td>', 'James, this really tugged at my heart strings as I''m a runner.  Since I''ve been home with my girls though, I don''t get out to the local running "path" like I used to.  Nice job capturing that emotion.  (not that it matters, but I gave this an 8 during voting.)', '2007-04-25 21:47:35.000000', NULL, 0),
